CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('teacher','student')), password_hash TEXT NOT NULL, synthetic INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT DEFAULT '', code TEXT UNIQUE, color TEXT DEFAULT '#42685b', teacher_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, name TEXT NOT NULL, join_code TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS class_members(class_id INTEGER REFERENCES classes(id) ON DELETE CASCADE, student_id INTEGER REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(class_id,student_id));
CREATE TABLE IF NOT EXISTS chapters(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, position INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS knowledge_points(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, chapter_id INTEGER REFERENCES chapters(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT DEFAULT '', x REAL DEFAULT 0, y REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS knowledge_edges(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, source INTEGER NOT NULL REFERENCES knowledge_points(id) ON DELETE CASCADE, target INTEGER NOT NULL REFERENCES knowledge_points(id) ON DELETE CASCADE, UNIQUE(source,target), CHECK(source<>target));
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, knowledge_id INTEGER REFERENCES knowledge_points(id) ON DELETE SET NULL, title TEXT NOT NULL, kind TEXT NOT NULL, content TEXT DEFAULT '', url TEXT DEFAULT '', version INTEGER DEFAULT 1, metadata TEXT DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resource_versions(id INTEGER PRIMARY KEY, resource_id INTEGER NOT NULL REFERENCES resources(id) ON DELETE CASCADE, version INTEGER NOT NULL, content TEXT, metadata TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, knowledge_id INTEGER NOT NULL REFERENCES knowledge_points(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, options TEXT DEFAULT '[]', answer TEXT NOT NULL, explanation TEXT DEFAULT '', difficulty INTEGER DEFAULT 1, hints TEXT DEFAULT '[]', rubric TEXT DEFAULT '{}', status TEXT DEFAULT 'approved');
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, class_id INTEGER REFERENCES classes(id) ON DELETE SET NULL, teacher_id INTEGER NOT NULL REFERENCES users(id), knowledge_id INTEGER REFERENCES knowledge_points(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT DEFAULT '', question_ids TEXT NOT NULL, student_ids TEXT DEFAULT '[]', due_at TEXT, status TEXT DEFAULT 'published', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE, assignment_id INTEGER REFERENCES assignments(id) ON DELETE SET NULL, answer TEXT NOT NULL, correct INTEGER, score REAL NOT NULL, hints_used INTEGER DEFAULT 0, error_type TEXT DEFAULT '', review_status TEXT DEFAULT 'automatic', feedback TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mastery(student_id INTEGER NOT NULL REFERENCES users(id), knowledge_id INTEGER NOT NULL REFERENCES knowledge_points(id) ON DELETE CASCADE, value REAL DEFAULT 0.2, evidence_count INTEGER DEFAULT 0, level TEXT DEFAULT 'unseen', updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(student_id,knowledge_id));
CREATE TABLE IF NOT EXISTS learning_events(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, knowledge_id INTEGER REFERENCES knowledge_points(id) ON DELETE SET NULL, kind TEXT NOT NULL, payload TEXT DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mistakes(student_id INTEGER NOT NULL REFERENCES users(id), question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE, wrong_count INTEGER DEFAULT 1, corrected INTEGER DEFAULT 0, error_type TEXT DEFAULT '', next_review_at TEXT DEFAULT CURRENT_TIMESTAMP, last_answer TEXT, PRIMARY KEY(student_id,question_id));
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, resource_id INTEGER REFERENCES resources(id) ON DELETE SET NULL, knowledge_id INTEGER REFERENCES knowledge_points(id) ON DELETE SET NULL, timestamp REAL DEFAULT 0, content TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classroom(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, prompt TEXT NOT NULL, kind TEXT DEFAULT 'question', active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classroom_responses(id INTEGER PRIMARY KEY, activity_id INTEGER NOT NULL REFERENCES classroom(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES users(id), answer TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(activity_id,student_id));
CREATE INDEX IF NOT EXISTS idx_attempts_student ON attempts(student_id,question_id);
CREATE INDEX IF NOT EXISTS idx_events_course ON learning_events(course_id,student_id);
CREATE INDEX IF NOT EXISTS idx_resources_course ON resources(course_id);
